CREATE OR REPLACE TYPE BODY t_money AS
  MEMBER FUNCTION plus(p_other IN t_money) RETURN t_money IS
  BEGIN
    RETURN t_money((SELF.amount + p_other.amount), SELF.currency);
  END;

  MAP MEMBER FUNCTION rank RETURN NUMBER IS
