CREATE OR REPLACE PACKAGE shapes_demo AS
  FUNCTION describe(p_s IN t_shape) RETURN VARCHAR2;
END shapes_demo;
/

CREATE OR REPLACE PACKAGE BODY shapes_demo AS

  FUNCTION describe(p_s IN t_shape) RETURN VARCHAR2 IS
    l_label VARCHAR2(4000);
  BEGIN
    l_label := '';
    IF (p_s) IS OF (t_circle) THEN
      l_label := 'round';
    ELSIF (p_s) IS OF (t_rectangle) THEN
      l_label := 'boxy';
    ELSIF (p_s) IS OF (t_triangle) THEN
      l_label := 'pointy';
    END IF;
    RETURN l_label;
  END describe;
END shapes_demo;
/